import {
    CSVExchange,
    defaultExchangeProvider,
    nullCandleStore,
    registerCSVExchange,
    setOrderBookSources,
    symbolNormalizers,
} from "scichart-scitrader";
import { DUMMY_EXCHANGE, DummyDataExchange, DummyOrderBookSource } from "./dummyData/DummyDataExchange";

/**
 * The sample data every demo charts, unless the demo is about a specific data source.
 *
 * Two CSV files of real Binance candles for BTCUSDT, ETHUSDT and SOLUSDT, regenerated by
 * `scripts/fetch-sample-csv.mjs`:
 *
 * - `crypto-1h.csv` — 90 days of hourly candles. Serves 1h up to 12h.
 * - `crypto-1d.csv` — 4 years of daily candles. Serves 1d, 1w and 1M.
 *
 * `CSVExchange` shifts both to end at the current time, so the demos always look live.
 */
export const SAMPLE_EXCHANGE = "CSV";
export const SAMPLE_SYMBOLS = ["BTCUSDT", "ETHUSDT", "SOLUSDT"];

let loading: Promise<CSVExchange> | undefined;

/**
 * Load the sample CSV files once and register them as the `"CSV"` exchange in the default
 * registry. Demos await this before creating a chart with `exchangeName: SAMPLE_EXCHANGE`.
 */
export function loadSampleData(): Promise<CSVExchange> {
    if (!loading) {
        loading = CSVExchange.fromUrl(["data/crypto-1h.csv", "data/crypto-1d.csv"], { name: SAMPLE_EXCHANGE }).then(
            (exchange) => {
                registerCSVExchange(defaultExchangeProvider, exchange);
                return exchange;
            }
        );
        loading.catch(() => {
            loading = undefined;
        });
    }
    return loading;
}

let dummyRegistered = false;

/**
 * Register the Sandbox's randomised market (`DummyDataExchange`) as the `"Dummy"` exchange, with
 * its order book. Used by the demos that need data the CSV files can't give: live ticks,
 * sub-hour intervals for watchlist sparklines, and a level-2 book.
 */
export function registerDummyData(): void {
    if (dummyRegistered) {
        return;
    }
    dummyRegistered = true;
    defaultExchangeProvider.registerExchange(new DummyDataExchange(), nullCandleStore);
    // Symbols are BASE + "USD"; the symbol picker and watchlist use this to split them.
    symbolNormalizers[DUMMY_EXCHANGE] = {
        parse: (s: string) => ({ base: s.replace(/USD$/, ""), quote: "USD" }),
        format: (p) => `${p.base}${p.quote}`,
    };
    setOrderBookSources(new Map([[DUMMY_EXCHANGE, new DummyOrderBookSource()]]));
}
